    prompt: { d: "M5.25 6.25 7 8l-1.75 1.75M8.5 10h2.25" },
  },
  branch: {
    a: { d: "M6.25 4a1.25 1.25 0 1 1-2.5 0a1.25 1.25 0 1 1 2.5 0" },
    b: { d: "M6.25 12a1.25 1.25 0 1 1-2.5 0a1.25 1.25 0 1 1 2.5 0" },
    c: { d: "M12.25 5a1.25 1.25 0 1 1-2.5 0a1.25 1.25 0 1 1 2.5 0" },
    trunk: { d: "M5 5.25v5.5" },
    twig: { d: "M11 6.25v.5a3 3 0 0 1-3 3H7.25a2.25 2.25 0 0 0-2.25 1" },
  },
  /* An amount of effort: a dial and its needle. */
  gauge: {
    dial: { d: "M2.75 11.75a5.25 5.25 0 1 1 10.5 0" },
    needle: { d: "M8 11.75l2.5-3.5" },
  },
  /* A panel with its column on the other side: show or hide a side panel at the end. */
  panel: {
    frame: { d: "M2.75 4.5A1.75 1.75 0 0 1 4.5 2.75h7a1.75 1.75 0 0 1 1.75 1.75v7a1.75 1.75 0 0 1-1.75 1.75h-7a1.75 1.75 0 0 1-1.75-1.75Z" },
    rail: { d: "M9.75 2.75 L9.75 13.25" },
  },
  /* What happened to a file: one rounded square, and inside it a plus, a
     dot, a minus or an arrow. They share the square and the bar, so a file
     whose change kind moves morphs only the mark. */
  "diff-added": {
    frame: { d: CHANGE_FRAME },
    bar: { d: "M5.5 8 L10.5 8" },
    stem: { d: "M8 10.5 L8 5.5" },
  },
  "diff-modified": {
    frame: { d: CHANGE_FRAME },
    dot: { d: "M8 8 L8.01 8", block: true },
  },
  "diff-removed": {
    frame: { d: CHANGE_FRAME },
    bar: { d: "M5.5 8 L10.5 8" },
  },
  "diff-renamed": {
    frame: { d: CHANGE_FRAME },
    bar: { d: "M5.5 8 L10.5 8" },
    head: { d: "M8.5 6 L10.5 8 L8.5 10" },
  },
} satisfies Record<string, Record<string, Stroke>>;

export type IconName = keyof typeof ICONS;

/** Every name in the set, in table order. */
export const ICON_NAMES = Object.keys(ICONS) as IconName[];

type Live = { id: string; key: string; s: Stroke; on: boolean; enter: boolean };
type State = { name: IconName; gen: number; live: Live[] };

const table = ICONS as Record<IconName, Record<string, Stroke>>;

/** Command letters and argument counts: `d` interpolates only when these match. */
const shape = (d: string) =>
  (d.match(/[a-zA-Z][^a-zA-Z]*/g) ?? []).map((c) => c[0] + ((c.slice(1).match(/-?[\d.]+(?:e-?\d+)?/g) ?? []).length)).join();

let morphD: boolean | undefined;
const canMorphD = () => (morphD ??= typeof CSS !== "undefined" && CSS.supports("d", 'path("M0 0")'));

function morphs(from: Stroke, to: Stroke) {
  if (Boolean(from.block) !== Boolean(to.block) || Boolean(from.cut) !== Boolean(to.cut)) return false;
  return from.d === to.d || (canMorphD() && shape(from.d) === shape(to.d));
}

function initial(name: IconName): State {
  return {
    name,
    gen: 0,
    live: Object.entries(table[name]).map(([key, s]) => ({ id: `${key}.0`, key, s, on: true, enter: false })),
  };
}

function next(prev: State, name: IconName): State {
  const want = table[name];
  const gen = prev.gen + 1;
  const taken = new Set<string>();
  const live: Live[] = [];
  for (const l of [...prev.live].sort((a, b) => Number(b.on) - Number(a.on))) {
    const s = want[l.key];
    if (s && !taken.has(l.key) && morphs(l.s, s)) {
      taken.add(l.key);
      live.push({ ...l, s, on: true, enter: !l.on });
    } else {
      live.push({ ...l, on: false, enter: false });
    }
  }
  for (const [key, s] of Object.entries(want)) {
    if (!taken.has(key)) live.push({ id: `${key}.${gen}`, key, s, on: true, enter: true });
  }
  const gone = live.filter((l) => !l.on);
  const drop = new Set(gone.slice(0, Math.max(0, gone.length - 8)).map((l) => l.id));
  return { name, gen, live: live.filter((l) => !drop.has(l.id)) };
}

const HIDE = 0.3;

// CSS `d` is set only after the first change; until then the attribute draws.
function dash(l: Live, morphing: boolean): CSSProperties | undefined {
  const f = l.s.f ?? 0;
  const t = l.s.t ?? 1;
  const len = t - f;
  const off = f === 0 ? len + HIDE : -(1 + HIDE);
  const style = {
    d: morphing ? `path("${l.s.d}")` : undefined,
    rotate: l.s.rot ? `${l.s.rot}deg` : undefined,
    "--len": len === 1 ? undefined : len,
    "--on": f === 0 ? undefined : -f,
    "--off": off === 1 + HIDE ? undefined : off,
  } as CSSProperties;
  return Object.values(style).some((v) => v !== undefined) ? style : undefined;
}

export type IconProps = Omit<ComponentProps<"svg">, "children"> & { name: IconName };

export function Icon({ name, className, ...props }: IconProps) {
  const [state, setState] = useState(() => initial(name));
  const mask = `icon-cut-${useId()}`;
  if (state.name !== name) setState(next(state, name));

  const cuts = state.live.filter((l) => l.s.cut);
  const path = (l: Live, extra?: string) => (
    <path
      key={l.id + (extra ?? "")}
      d={l.s.d}
      pathLength={1}
      className={[styles.stroke, l.s.block && styles.block, l.s.seam && styles.seam, l.s.fx && styles[l.s.fx], extra].filter(Boolean).join(" ")}
      data-off={l.on ? undefined : ""}
      data-enter={l.enter ? "" : undefined}
      style={dash(l, state.gen > 0)}
      onTransitionEnd={
        l.on || extra
          ? undefined
          : (e) => {
              if (e.propertyName === "stroke-dashoffset") {
                setState((s) => ({ ...s, live: s.live.filter((x) => x.id !== l.id || x.on) }));
              }
            }
      }
    />
  );

  return (
    // Size attributes keep it from drawing huge before CSS loads.
    <svg
      viewBox="0 0 16 16"
      width="16"
      height="16"
      aria-hidden="true"
      data-icon={name}
      data-ready={state.gen > 0 ? "" : undefined}
      className={className ? `${styles.icon} ${className}` : styles.icon}
      {...props}
    >
      {cuts.length > 0 && (
        <mask id={mask} maskUnits="userSpaceOnUse" x="0" y="0" width="16" height="16">
          <rect width="16" height="16" fill="white" stroke="none" />
          {cuts.map((l) => path(l, styles.cut))}
        </mask>
      )}
      <g mask={cuts.length > 0 ? `url(#${mask})` : undefined}>{state.live.filter((l) => !l.s.cut).map((l) => path(l))}</g>
      {cuts.map((l) => path(l))}
    </svg>
  );
}

@layer theme, base, components, utilities;

/* Shared text utilities; other components compose these classes. */

/* The fade only shows when text overflows: otherwise the scroll timeline is inactive. */

@property --truncate-fade {
  syntax: "<length>";
  inherits: false;
  initial-value: 0px;
}

@layer components {
  /* Text that's never cut: a long name, email or path breaks onto the next
     line, inside a word only when there's nowhere else to break. Use this for
     anything a person needs to read in full. */
  .wrap {
    min-width: 0;
    overflow-wrap: anywhere;
    text-wrap: pretty;
  }

  /* One line, fading at the end when cut. Only for rows that must keep a
     fixed height (a virtualized table); give the full text a title too. The padding/negative margin stops
     overflow: hidden clipping descenders and accents at tight line heights. */
  .truncate {
    min-width: 0;
    overflow: hidden;
    white-space: nowrap;
    padding-block: 0.2em;
    margin-block: -0.2em;
  }

  /* Several lines; set --truncate-lines (default 2). */
  .truncateLines {
    overflow: hidden;
    max-height: calc(var(--truncate-lines, 2) * 1lh);
  }

  @supports (animation-timeline: scroll()) {
    .truncate,
    .truncateLines {
      --truncate-to: right;
      animation: truncate-overflow linear both;
    }

    :is([dir="rtl"]) .truncate,
    :is([dir="rtl"]) .truncateLines {
      --truncate-to: left;
    }

    .truncate {
      mask-image: linear-gradient(to var(--truncate-to), #000 calc(100% - var(--truncate-fade)), transparent);
      animation-timeline: scroll(self inline);
    }

    .truncateLines {
      mask-image:
        linear-gradient(#000 0 0),
        linear-gradient(to var(--truncate-to), #000 calc(100% - var(--truncate-fade)), transparent);
      mask-size: 100% calc(100% - 1lh), 100% 1lh;
      mask-position: top, bottom;
      mask-repeat: no-repeat;
      animation-timeline: scroll(self block);
    }
  }

  /* Without scroll timelines, fall back to an ellipsis. */
  @supports not (animation-timeline: scroll()) {
    .truncate {
      text-overflow: ellipsis;
    }

    .truncateLines {
      display: -webkit-box;
      -webkit-box-orient: vertical;
      -webkit-line-clamp: var(--truncate-lines, 2);
    }
  }

  @keyframes truncate-overflow {
    from,
    to {
      --truncate-fade: 24px;
    }
  }

  /* Visually hidden, still read by screen readers. */
  .srOnly {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
  }

  /* Work in progress: a light band sweeps across dimmed text. --sweep-dim sets the dim. */
  .sweep {
    mask-image: linear-gradient(
      90deg,
      rgb(0 0 0 / var(--sweep-dim, 0.55)) 35%,
      #000 50%,
      rgb(0 0 0 / var(--sweep-dim, 0.55)) 65%
    );
    mask-size: 300% 100%;
    mask-repeat: no-repeat;
    animation: sweep var(--ui-dur-sweep) linear infinite;
  }

  @keyframes sweep {
    from {
      mask-position: 100% 0;
    }
    to {
      mask-position: 0 0;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .sweep {
      mask-image: none;
      animation: none;
    }
  }
}

@layer theme, base, components, utilities;

.srOnly {
  composes: srOnly from "../text/text.module.css";
}

.label {
  composes: wrap from "../text/text.module.css";
}

.mark {
  composes: icon from "../icons/icons.module.css";
}

@layer components {
  /* ---------- Group ---------- */

  .group {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: var(--ui-gap-inline);
    min-width: 0;
  }

  .group:focus {
    outline: none;
  }

  /* ---------- Shared ---------- */

  .chip,
  .removable {
    --chip-font: var(--ui-weight-medium) var(--ui-text-md) / 1 var(--ui-font-sans);
    --ui-icon-stroke: var(--ui-icon-stroke-medium);
    position: relative;
    display: inline-flex;
    flex-shrink: 0;
    align-items: center;
    box-sizing: border-box;
    max-width: 100%;
    min-height: var(--ui-control-sm);
    /* A pill while it's one line; a long label wraps and the corners stay
       the pill's, so it becomes a rounded box rather than cutting the text. */
    border-radius: calc(var(--ui-control-sm) / 2);
    isolation: isolate;
    font: var(--chip-font);
    line-height: 1.3;
  }

  /* ---------- Toggle chip ---------- */

  .chip {
    --chip-bg: var(--ui-surface);
    --chip-bg-hover: var(--ui-fill-solid);
    --chip-bg-press: var(--ui-fill-strong-solid);
    --chip-edge: var(--ui-border-strong);
    --chip-edge-hover: var(--ui-field-focus);
    --chip-mark: var(--ui-muted);

    gap: 6px;
    /* The label ends half the height in, where the round end stops; the mark
       carries air in its own box, so its side is a step less. */
    padding-inline: var(--ui-pad-tag) calc(var(--ui-control-sm) / 2);
    margin: 0;
    border: 0;
    background: none;
    color: var(--ui-foreground);
    cursor: pointer;
    user-select: none;
    touch-action: manipulation;
    -webkit-tap-highlight-color: transparent;
    transition: color var(--ui-dur-instant) var(--ui-ease-color);
  }

  .chip[aria-pressed="true"] {
    --chip-bg: light-dark(
      color-mix(in oklch, var(--ui-accent) 10%, var(--ui-surface)),
      color-mix(in oklch, var(--ui-accent) 18%, var(--ui-surface))
    );
    --chip-bg-hover: light-dark(
      color-mix(in oklch, var(--ui-accent) 14%, var(--ui-surface)),
      color-mix(in oklch, var(--ui-accent) 23%, var(--ui-surface))
    );
    --chip-bg-press: light-dark(
      color-mix(in oklch, var(--ui-accent) 19%, var(--ui-surface)),
      color-mix(in oklch, var(--ui-accent) 28%, var(--ui-surface))
    );
    --chip-edge: var(--ui-border-accent);
    --chip-edge-hover: var(--ui-border-accent);
    --chip-mark: var(--ui-accent-text);
    color: var(--ui-accent-text);
  }

  .chip::before {
    content: "";
    position: absolute;
    inset: 0;
    z-index: -1;
    border-radius: inherit;
    background: var(--chip-bg);
    box-shadow: inset 0 0 0 var(--ui-hairline) var(--chip-edge);
    transition:
      background-color var(--ui-dur-instant) var(--ui-ease-color),
      box-shadow var(--ui-dur-instant) var(--ui-ease-color);
  }

  .mark {
    color: var(--chip-mark);
    transition: color var(--ui-dur-instant) var(--ui-ease-color);
  }

  /* Plus to check: each bar (pathLength 1) rotates about where it meets its
     check leg and its dash trims to that leg. The numbers match the Icon check. */
  .short,
  .long {
    transform-box: view-box;
    stroke-dasharray: 1 3;
    stroke-dashoffset: 0;
    transition:
      rotate var(--ui-dur-move) var(--ui-ease-move),
      stroke-dasharray var(--ui-dur-move) var(--ui-ease-move),
      stroke-dashoffset var(--ui-dur-move) var(--ui-ease-move);
  }

  .short {
    transform-origin: 3.5px 8px;
  }

  .long {
    transform-origin: 8px 9.83px;
  }

  .chip[aria-pressed="true"] .short {
    rotate: 45deg;
    stroke-dasharray: 0.4465 3;
    stroke-dashoffset: -0.0636;
  }

  .chip[aria-pressed="true"] .long {
    rotate: 41.35deg;
    stroke-dasharray: 0.8763 3;
    stroke-dashoffset: -0.1083;
  }

  @media (hover: hover) {
    .chip:hover:not(:disabled)::before {
      background: var(--chip-bg-hover);
      box-shadow: inset 0 0 0 var(--ui-hairline) var(--chip-edge-hover);
    }
    .chip:hover:not(:disabled) .mark {
      color: currentColor;
    }
  }

  .chip:active:not(:disabled)::before {
    background: var(--chip-bg-press);
    transition-duration: var(--ui-dur-press);
  }

  .chip:focus-visible {
    outline: var(--ui-ring-focus);
    outline-offset: var(--ui-ring-offset);
  }

  .chip:disabled {
    opacity: 0.5;
    cursor: default;
  }

  @media (pointer: coarse) {
    .chip::after {
      content: "";
      position: absolute;
      inset: -3px 0;
    }
  }

  /* ---------- Removable chip ---------- */

  .removable {
    --chip-inset: 4px;
    --chip-remove: calc(var(--ui-control-sm) - var(--chip-inset) * 2);
    gap: 2px;
    padding-inline: calc(var(--ui-control-sm) / 2) var(--chip-inset);
    background: var(--ui-fill-strong);
    color: var(--ui-foreground);
    /* The component waits for this opacity transition's end before removing. */
    transition: opacity var(--ui-dur-fast) var(--ui-ease-enter);
  }

  .removable[data-leaving] {
    opacity: 0;
    pointer-events: none;
    transition: opacity var(--ui-dur-instant) var(--ui-ease-exit);
  }

  @starting-style {
    .group[data-ready] .removable {
      opacity: 0;
    }
  }

  .remove {
    position: relative;
    display: grid;
    flex-shrink: 0;
    place-items: center;
    width: var(--chip-remove);
    height: var(--chip-remove);
    padding: 0;
    margin: 0;
    border: 0;
    border-radius: var(--ui-radius-full);
    background: none;
    color: var(--ui-muted);
    cursor: pointer;
    user-select: none;
    touch-action: manipulation;
    -webkit-tap-highlight-color: transparent;
    transition: color var(--ui-dur-instant) var(--ui-ease-color);
  }

  .remove::before {
    content: "";
    position: absolute;
    inset: 0;
    z-index: -1;
    border-radius: inherit;
    transition: background-color var(--ui-dur-instant) var(--ui-ease-color);
  }

  @media (hover: hover) {
    /* Hover only darkens the ×: a circle behind it would read as a second
       chip inside the first. */
    .remove:hover:not([aria-disabled]) {
      color: var(--ui-foreground);
    }
  }

  .remove:active:not([aria-disabled]) {
    color: var(--ui-foreground);
  }

  .remove:active:not([aria-disabled])::before {
    background: color-mix(in oklch, var(--ui-foreground) 13%, transparent);
    transition-duration: var(--ui-dur-press);
  }

  .remove:focus-visible {
    outline: var(--ui-ring-focus);
    outline-offset: var(--ui-ring-offset);
    color: var(--ui-foreground);
  }

  @media (pointer: coarse) {
    .remove::after {
      content: "";
      position: absolute;
      inset: calc((var(--chip-remove) - 40px) / 2);
    }
  }

  @media (forced-colors: active) {
    .chip,
    .removable {
      border: 1px solid ButtonText;
    }
    .chip[aria-pressed="true"] {
      outline: 2px solid Highlight;
      outline-offset: -3px;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    .removable,
    .removable[data-leaving],
    .short,
    .long {
      transition: none;
    }
  }
}

"use client";

import {
  createContext,
  useContext,
    useEffect,
  useLayoutEffect,
  useRef,
  useState,
  type ComponentProps,
  type MouseEvent,
  type ReactNode,
  type TransitionEvent,
} from "react";
import { Icon } from "../icons/icons";
import styles from "./chip.module.css";

type ChipProps = Omit<ComponentProps<"button">, "children"> & {
  children: ReactNode;
  pressed?: boolean;
  defaultPressed?: boolean;
  onPressedChange?: (pressed: boolean) => void;
};

/** A toggle filter: a button with aria-pressed whose plus turns into a check. */
export function Chip({
  pressed: controlled,
  defaultPressed = false,
  onPressedChange,
  onClick,
  type = "button",
  className,
  children,
  ...props
}: ChipProps) {
  const [own, setOwn] = useState(defaultPressed);
  const pressed = controlled ?? own;

  function handleClick(event: MouseEvent<HTMLButtonElement>) {
    onClick?.(event);
    if (event.defaultPrevented) return;
    if (controlled === undefined) setOwn(!pressed);
    onPressedChange?.(!pressed);
  }

  return (
    <button
      type={type}
      data-chip=""
      aria-pressed={pressed}
      className={className ? `${styles.chip} ${className}` : styles.chip}
      onClick={handleClick}
      {...props}
    >
      <svg viewBox="0 0 16 16" width="16" height="16" aria-hidden="true" className={styles.mark}>
        <path d="M3.25 8 L12.75 8" pathLength={1} className={styles.short} />
        <path d="M8 12.75 L8 3.25" pathLength={1} className={styles.long} />
      </svg>
      <span className={styles.label}>{children}</span>
    </button>
  );
}

type Snapshot = { rects: Map<Element, DOMRect>; index: number; refocus: boolean; name: string };

const GroupContext = createContext<{ beforeRemove: (chip: HTMLElement) => void } | null>(null);

type ChipGroupProps = ComponentProps<"div"> & {
  /** Group name, e.g. "Dietary filters"; or pass `aria-labelledby`. */
  "aria-label"?: string;
};

const token = (el: Element, name: string, fallback: string) => getComputedStyle(el).getPropertyValue(name).trim() || fallback;
const ms = (value: string) => (value.endsWith("ms") ? parseFloat(value) : parseFloat(value) * 1000);
const reduced = () => matchMedia("(prefers-reduced-motion: reduce)").matches;

/** A wrapping row of chips that animates and announces removals. */
export function ChipGroup({ className, children, ...props }: ChipGroupProps) {
  const ref = useRef<HTMLDivElement>(null);
  const snapshot = useRef<Snapshot | null>(null);
  const status = useRef<HTMLSpanElement>(null);
  // Gates the @starting-style fade so only chips added later fade in.
  useEffect(() => ref.current?.setAttribute("data-ready", ""), []);

  const chips = () => Array.from(ref.current?.querySelectorAll<HTMLElement>("[data-chip]") ?? []);

  function beforeRemove(chip: HTMLElement) {
    const all = chips();
    snapshot.current = {
      rects: new Map(all.map((el) => [el, el.getBoundingClientRect()])),
      index: all.indexOf(chip),
      refocus: chip.contains(document.activeElement),
      name: chip.querySelector("[data-label]")?.textContent ?? "",
    };
  }

  useLayoutEffect(() => {
    const before = snapshot.current;
    const group = ref.current;
    if (!before || !group) return;
    snapshot.current = null;
    const all = chips();
    if (all.length >= before.rects.size) return;

    if (status.current && before.name) status.current.textContent = `Removed ${before.name}`;

    if (!reduced()) {
      const easing = token(group, "--ui-ease-move", "ease-out");
      const duration = ms(token(group, "--ui-dur-move", "320ms"));
      for (const el of all) {
        const from = before.rects.get(el);
        if (!from) continue;
        const to = el.getBoundingClientRect();
        const dx = from.left - to.left;
        const dy = from.top - to.top;
        if (Math.abs(dx) > 0.5 || Math.abs(dy) > 0.5) {
          el.animate({ translate: [`${dx}px ${dy}px`, "0 0"] }, { duration, easing });
        }
      }
    }

    if (before.refocus) {
      const next = all[Math.min(before.index, all.length - 1)];
      const target = next?.querySelector<HTMLElement>("[data-remove], button") ?? next;
      if (target) target.focus();
      else {
        // Focusable only for now, so clicks between chips never steal focus.
        group.tabIndex = -1;
        group.focus();
        group.addEventListener("blur", () => group.removeAttribute("tabindex"), { once: true });
      }
    }
  });

  return (
    <GroupContext.Provider value={{ beforeRemove }}>
      <div
        ref={ref}
        role="group"
        className={className ? `${styles.group} ${className}` : styles.group}
        {...props}
      >
        {children}
        <span ref={status} role="status" className={styles.srOnly} />
      </div>
    </GroupContext.Provider>
  );
}

type RemovableChipProps = Omit<ComponentProps<"span">, "children"> & {
  children: ReactNode;
  /** Called after the fade-out; remove it from your list here. */
  onRemove: () => void;
  /** Defaults to "Remove {label}" for text labels. */
  removeLabel?: string;
};

/** A chosen value with a remove button. */
export function RemovableChip({
  children,
  onRemove,
  removeLabel,
  className,
  ...props
}: RemovableChipProps) {
  const group = useContext(GroupContext);
  const ref = useRef<HTMLSpanElement>(null);
  const [leaving, setLeaving] = useState(false);
  const name = removeLabel ?? (typeof children === "string" || typeof children === "number" ? `Remove ${children}` : "Remove");

  function gone() {
    if (ref.current) group?.beforeRemove(ref.current);
    onRemove();
    requestAnimationFrame(() => requestAnimationFrame(() => ref.current?.isConnected && setLeaving(false)));
  }

  function remove() {
    if (leaving) return;
    // No transition will fire under reduced motion.
    if (reduced()) return gone();
    setLeaving(true);
  }

  function finish(event: TransitionEvent<HTMLSpanElement>) {
    if (leaving && event.target === event.currentTarget && event.propertyName === "opacity") gone();
  }

  return (
    <span
      {...props}
      ref={ref}
      data-chip=""
      data-leaving={leaving || undefined}
      className={className ? `${styles.removable} ${className}` : styles.removable}
      onTransitionEnd={finish}
    >
      <span className={styles.label} data-label="">
        {children}
      </span>
      <button
        type="button"
        data-remove=""
        className={styles.remove}
        aria-label={name}
        // Not `disabled`, which would drop focus before the group moves it.
        aria-disabled={leaving || undefined}
        onClick={remove}
      >
        <Icon name="close" />
      </button>
    </span>
  );
}
